import json
import itertools

def build_adjacency(edges):
    adj = {}
    for a, b in edges:
        adj.setdefault(a, set()).add(b)
        adj.setdefault(b, set()).add(a)
    return adj

def is_valid_path(path, adj):
    return all(path[i+1] in adj.get(path[i], set()) for i in range(len(path)-1))

def find_hamiltonian_path(cities, adj, end_city):
    for perm in itertools.permutations(cities):
        if perm[-1] != end_city:
            continue
        if is_valid_path(perm, adj):
            return list(perm)
    return None

def compute_flight_days(order, durations, total_days):
    # Number of flights equals len(order)-1
    n = len(order)
    flights = []
    # f_k = sum_{j=1..k} d_j - (k-1)
    running_sum = 0
    for k in range(n-1):
        running_sum += durations[order[k]]
        f_k = running_sum - (k)
        flights.append(f_k)
    # Validate last flight aligns with remaining days
    last_city = order[-1]
    expected_last_flight_day = total_days - durations[last_city] + 1
    return flights, expected_last_flight_day

def build_itinerary(order, flights, total_days):
    itinerary = []
    for i, city in enumerate(order):
        if i == 0:
            start = 1
            end = flights[0]
        elif i < len(order) - 1:
            start = flights[i-1]
            end = flights[i]
        else:
            start = flights[-1]
            end = total_days
        itinerary.append({"day_range": f"Day {start}-{end}", "place": city})
    return itinerary

def validate_constraints(order, durations, total_days, flights, expected_last_flight_day, conference_city, conference_days):
    # Sum of desired durations must equal total_days + number_of_flights
    sum_durations = sum(durations[c] for c in order)
    if sum_durations != total_days + (len(order) - 1):
        return False, "Sum of desired days must equal total days plus number of flights (overlap days)."
    # Flight days must be strictly increasing and within [1, total_days]
    if not all(1 <= d <= total_days for d in flights):
        return False, "Flight days out of bounds."
    if any(flights[i] >= flights[i+1] for i in range(len(flights)-1)):
        return False, "Flight days not strictly increasing."
    # Last city must be conference city
    if order[-1] != conference_city:
        return False, "Conference city must be the last city in the path."
    # Last flight day must align with expected (to satisfy exact last city's stay)
    if flights[-1] != expected_last_flight_day:
        return False, "Last flight day does not align with required stay for the conference city."
    # Ensure conference days are within the last city's occupied day range
    last_city_start = flights[-1]
    last_city_end = total_days
    if not all(last_city_start <= d <= last_city_end for d in conference_days):
        return False, "Conference days are not within the last city's occupied days."
    # Ensure exact stay days per city are met using overlap accounting
    # City i occupies: [start_i, end_i] where start_0=1, end_0=f1; start_i=f_{i-1}, end_i=f_i for middle; last: start=f_{n-1}, end=total_days
    # Counted days per city = end - start + 1
    counted = []
    for i in range(len(order)):
        if i == 0:
            start = 1
            end = flights[0]
        elif i < len(order) - 1:
            start = flights[i-1]
            end = flights[i]
        else:
            start = flights[-1]
            end = total_days
        counted.append(end - start + 1)
    for city, c_days in zip(order, counted):
        if c_days != durations[city]:
            return False, f"City {city} counted days {c_days} does not equal desired {durations[city]}."
    return True, ""

def main():
    # Input variables (trip constraints)
    total_days = 14
    desired_stays = {
        "Vilnius": 4,
        "Split": 5,
        "Madrid": 6,
        "Santorini": 2
    }
    cities = list(desired_stays.keys())
    direct_flights = [
        ("Vilnius", "Split"),
        ("Split", "Madrid"),
        ("Madrid", "Santorini")
    ]
    conference_city = "Santorini"
    conference_days = [13, 14]

    # Build adjacency map
    adj = build_adjacency(direct_flights)

    # Find a Hamiltonian path that ends in the conference city
    path = find_hamiltonian_path(cities, adj, conference_city)
    if not path:
        print(json.dumps({"error": "No feasible city ordering with given direct flights and constraints."}))
        return

    # Compute flight days and validate last flight alignment
    flights, expected_last_flight_day = compute_flight_days(path, desired_stays, total_days)

    # Validate all constraints
    ok, msg = validate_constraints(path, desired_stays, total_days, flights, expected_last_flight_day, conference_city, conference_days)
    if not ok:
        print(json.dumps({"error": msg}))
        return

    # Build itinerary with overlapping day ranges on flight days
    itinerary = build_itinerary(path, flights, total_days)

    # Output as JSON
    print(json.dumps({"itinerary": itinerary}, ensure_ascii=False))

if __name__ == "__main__":
    main()
